alter table public.enterprise_esg_assets add column if not exists evidence_note text, add column if not exists metric_label text, add column if not exists metric_value numeric, add column if not exists metric_unit text, add column if not exists sdg_tags text[] not null default '{}', add column if not exists report_ready boolean not null default false; create index if not exists idx_enterprise_esg_assets_enterprise_status_created on public.enterprise_esg_assets(enterprise_id,status,created_at desc); create or replace function public.admin_finalize_esg_asset(p_asset_id uuid,p_title text,p_summary text,p_period_label text default null,p_evidence_note text default null,p_metric_label text default null,p_metric_value numeric default null,p_metric_unit text default null,p_sdg_tags text[] default '{}',p_note text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); v_enterprise uuid; begin if v_actor is null or not exists(select 1 from public.admin_roles where user_id=v_actor and role_key in ('super_admin','admin','outcome_reviewer','enterprise_reviewer')) then raise exception 'insufficient_privilege'; end if; if coalesce(trim(p_title),'')='' or coalesce(trim(p_summary),'')='' then raise exception 'content_required'; end if; if p_metric_value is not null and coalesce(trim(p_metric_label),'')='' then raise exception 'metric_label_required'; end if; update public.enterprise_esg_assets set title=p_title,summary=p_summary,period_label=p_period_label,evidence_note=p_evidence_note,metric_label=p_metric_label,metric_value=p_metric_value,metric_unit=p_metric_unit,sdg_tags=coalesce(p_sdg_tags,'{}'),report_ready=true,status='approved',updated_at=now() where id=p_asset_id and status in ('draft','submitted','needs_info','approved') returning enterprise_id into v_enterprise; if not found then raise exception 'asset_not_finalizable'; end if; insert into public.audit_logs(actor_user_id,actor_role,action,subject_type,subject_id,note) values(v_actor,'outcome_reviewer','finalize_esg_asset','enterprise_esg_asset',p_asset_id::text,p_note); insert into public.user_notifications(recipient_user_id,kind,title,body,related_type,related_id) select eu.user_id,'esg_report_asset_ready','ESG 報告素材已完成','一筆已核實成果已整理成可供 ESG／永續報告引用的素材。','enterprise_esg_asset',p_asset_id from public.enterprise_users eu where eu.enterprise_id=v_enterprise and not exists(select 1 from public.user_notifications n where n.recipient_user_id=eu.user_id and n.related_type='enterprise_esg_asset' and n.related_id=p_asset_id and n.kind='esg_report_asset_ready'); end; $$; revoke all on function public.admin_finalize_esg_asset(uuid,text,text,text,text,text,numeric,text,text[],text) from public,anon; grant execute on function public.admin_finalize_esg_asset(uuid,text,text,text,text,text,numeric,text,text[],text) to authenticated;
